import type {TopicId} from './topics.ts';

/**
 * A small looping drawing of each mechanism, in the same material language as
 * the 3D studios: steel, stone, timber and rope, with orange for the force you
 * supply. The motion is CSS, defined alongside the gallery styles, and it stops
 * for anyone who asks for reduced motion.
 */
export default function Vignette({topic}: {topic: TopicId}) {
  return (
    <div className="vignette" aria-hidden="true">
      <svg viewBox="0 0 260 132" preserveAspectRatio="xMidYMid meet">{art[topic]}</svg>
    </div>
  );
}

