/**
 * The two numbers the adder in the gallery is adding, most significant bit
 * first, and their sum worked out here rather than transcribed. A drawing of an
 * addition that does not add up is worse than no drawing at all, and nothing
 * about the picture would give it away.
 */
const ADD_A = [1, 0, 0, 1, 1, 0, 1, 0];
const ADD_B = [0, 1, 1, 0, 1, 1, 0, 1];
const ADD_BITS = ADD_A.map((_, i) => i);
const ADD_TOTAL = parseInt(ADD_A.join(''), 2) + parseInt(ADD_B.join(''), 2);
const ADD_SUM = ADD_TOTAL.toString(2).padStart(9, '0').slice(-8).split('').map(Number);
const ADD_CARRY = ADD_TOTAL > 255 ? 1 : 0;

